import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0014: 为什么禁止普通依赖图循环","description":"","frontmatter":{},"headers":[],"relativePath":"zh/adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md","filePath":"zh/adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md","lastUpdated":0}`),a={name:`zh/adr/ADR-0014-why-ordinary-dependency-cycles-are-forbidden.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0014-为什么禁止普通依赖图循环" tabindex="-1">ADR-0014: 为什么禁止普通依赖图循环 <a class="header-anchor" href="#adr-0014-为什么禁止普通依赖图循环" aria-label="Permalink to “ADR-0014: 为什么禁止普通依赖图循环”">​</a></h1><ul><li>状态：已接受</li><li>日期：2026-10-31</li><li>关联：resources.md §3.5，ADR-0004</li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to “背景”">​</a></h2><p>A 依赖 B、B 又依赖 A 时，恢复顺序在逻辑上无解：两边都&quot;等对方先健康&quot;， 形成互相等待。这种环若在运行期才发现，表现为死锁或随机顺序的乱修； 配置错误会静默潜伏。</p><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to “决策”">​</a></h2><p>普通依赖图必须无环：配置加载期（<code>DependencyGraph::build</code>）做环检测， 检出即拒绝启动并打印具体环路径（<code>a -&gt; b -&gt; a</code>）；用户无法通过运行期 兜底来&quot;打破&quot;环。表达&quot;互为备份&quot;这类合法的对称关系用 <code>alternative_groups</code> （冗余组，required_count 语义）而不是环。</p><h2 id="替代方案" tabindex="-1">替代方案 <a class="header-anchor" href="#替代方案" aria-label="Permalink to “替代方案”">​</a></h2><ul><li><strong>运行期打破环（超时/仲裁）</strong>：行为不可预测，恢复顺序取决于竞态胜负。</li><li><strong>允许环 + 拓扑排序容错</strong>：排序算法对环的输出是任意的，等于随机恢复。</li></ul><h2 id="优缺点" tabindex="-1">优缺点 <a class="header-anchor" href="#优缺点" aria-label="Permalink to “优缺点”">​</a></h2><p>优点：启动期把不可恢复的建模错误一次性拒绝；恢复顺序永远良定义（拓扑序）。 缺点：互为依赖的建模需求要走 alternative_groups（学习成本）。</p><h2 id="后续影响" tabindex="-1">后续影响 <a class="header-anchor" href="#后续影响" aria-label="Permalink to “后续影响”">​</a></h2><ul><li>条件依赖（<code>conditional_on</code>）是有向无环内的特殊激活边，同样受环检测约束。</li><li>配置校验错误必须包含完整环路径（tests: rejects_dependency_cycle_at_startup）。</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};